    21	/**
    22	 * Maps a 0-based source line to the `MarkdownRenderer.render` output, which
    23	 * has no source-line mapping but emits one top-level element per section.
    24	 */
    25	export const locateTaggedLine = ({
    26	  sections,
    27	  listItems = [],
    28	  line,
    29	}: {
    30	  sections: SectionCache[];
    31	  listItems?: ListItemCache[];
    32	  line: number;
    33	}): TaggedLineTarget | null => {
    34	  const blocks = sections.filter(rendersInPlace);
    35	  const covers = ({ position }: CacheItem): boolean =>
    36	    position.start.line <= line && line <= position.end.line;
    37	  const blockIndex = blocks.findIndex(covers);
    38	  const block = blocks[blockIndex];
    39	  if (!block) return null;
    40	
    41	  const target = { blockIndex, blockCount: blocks.length };
    42	  const { start, end } = block.position;
    43	  if (block.type === "list") {
    44	    const items = listItems
    45	      .filter(
    46	        ({ position }) =>
    47	          start.line <= position.start.line && position.start.line <= end.line,
    48	      )
    49	      .sort((a, b) => a.position.start.line - b.position.start.line);
    50	    // Nested items start later, so the last covering item is the innermost.
    51	    const index = items.map(covers).lastIndexOf(true);
    52	    return index === -1
    53	      ? target
    54	      : { ...target, item: { kind: "li", index, count: items.length } };
    55	  }
